/* Compact, keyboard-operable event search; every existing criterion remains mounted. */
.events-filter .event-filter-main{display:grid;grid-template-columns:minmax(240px,1.4fr) minmax(230px,1fr);gap:18px;align-items:end}
.events-filter .event-filter-main label{margin-bottom:0}
.events-filter .event-filter-main-actions{display:flex;gap:10px;flex-wrap:wrap}
.events-filter .event-filter-main-actions button{min-height:44px}
.events-filter .event-filter-advanced{margin-top:12px;border-top:1px solid var(--line);padding-top:10px}
.events-filter .event-filter-advanced>summary{cursor:pointer;color:var(--green);font-weight:650;text-underline-offset:4px}
.events-filter .event-filter-advanced[open] .event-filter-grid{margin-top:12px}
@media(max-width:700px){.events-filter .event-filter-main{grid-template-columns:1fr}.events-filter .event-filter-main-actions{display:grid;grid-template-columns:1fr 1fr}}
.events-filter .event-filter-advanced>summary:focus-visible{outline:3px solid #d49438;outline-offset:3px;border-radius:3px}

